-- Inventory catalog seeded from "Unit Price | Project BOM" (tab 2) of
-- BLANCH TBWC Price Workbook (D) NPIE R01-0126.xlsm.
-- Follows naming convention: {tablename}_id primary key.
DROP TABLE IF EXISTS public.inventory CASCADE;
CREATE TABLE public.inventory (
  inventory_id      bigint NOT NULL GENERATED ALWAYS AS IDENTITY,
  part_number       text NOT NULL,
  description       text,
  category          text,
  base_price        numeric(15,2),
  msrp              numeric(15,2),
  moq               integer,
  dnet_cost         numeric(15,2),
  unit_weight       numeric(12,3),
  pack_qty          integer,
  service_days      integer,
  distribution_type text,
  upc_code          text,
  is_active         boolean NOT NULL DEFAULT true,
  created_at        timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT inventory_pkey PRIMARY KEY (inventory_id)
) TABLESPACE pg_default;

CREATE INDEX inventory_part_number_idx ON public.inventory (part_number);
CREATE INDEX inventory_category_idx    ON public.inventory (category);

ALTER TABLE public.inventory OWNER to postgres;
GRANT ALL ON TABLE public.inventory TO anon, authenticated, postgres, service_role;

